"""Literal original save() grid; direct child LOCK does not substitute parent geometry."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const esc=','const icons=','const icon=','const t=','const btn=','const notice=','const heading=','function save(')))
cases=[dict(id=f'{lang}-{width}-{i}',lang=lang,width=width,selected=selected)for lang in ['ko','en']for width in [656,657,700,904.25,980,1060]for i,selected in enumerate([['json'],[],['csv','html'],['json','csv','html']])]
(o/'saveoptions-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
script="let lang='ko',state={formats:new Set(['json']),saved:false};"+defs+'\nconst cases='+json.dumps(cases)+""";for(const c of cases){const f=document.createElement('div');f.className='fixture';f.dataset.id=c.id;f.style.width=c.width+'px';lang=c.lang;state.formats=new Set(c.selected);const tmp=document.createElement('div');tmp.innerHTML=save();f.append(tmp.querySelector('.download-options'));document.getElementById('fixtures').append(f)}
function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const e=f.firstChild,r=e.getBoundingClientRect(),b=x=>{const q=x.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}};return{id:f.dataset.id,width:r.width,height:r.height,options:[...e.children].map(c=>({format:c.querySelector('input').dataset.format,selected:c.querySelector('input').checked,card:b(c),checkbox:b(c.querySelector('input')),body:b(c.querySelector('span')),title:b(c.querySelector('strong'))}))}})}
const first=document.querySelector('.fixture');let selected=new Set(['json']),english=false,changes=0;function render(){const before=document.activeElement,identity=before?.dataset?.format;lang=english?'en':'ko';state.formats=selected;const tmp=document.createElement('div');tmp.innerHTML=save();first.replaceChildren(tmp.querySelector('.download-options'));if(identity)first.querySelector(`[data-format="${identity}"]`).focus({preventScroll:true});live()}
function live(){const a=document.activeElement;document.getElementById('live').textContent=JSON.stringify({selected:[...selected],changes,focused:a?.dataset?.format||null,focusVisible:a?.matches(':focus-visible')||false,english,downloadEnabled:selected.size>0})}first.addEventListener('change',e=>{const f=e.target.dataset.format;if(e.target.checked)selected.add(f);else selected.delete(f);changes++;render()});for(const k of ['focusin','focusout','keydown','keyup','pointerup'])first.addEventListener(k,()=>setTimeout(live,0));document.getElementById('language').onclick=()=>{english=!english;render()};live();
document.getElementById('saveoptions-record').onclick=async()=>{await document.fonts.ready;const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read()})});if(!res.ok)throw Error('Evidence failed');document.getElementById('saveoptions-record').textContent='SaveOptions recorded'};"""
(o/'saveoptions.html').write_text('<!doctype html><meta charset="utf-8"><title>SaveOptions · original isolation</title><link rel="stylesheet" href="saveoptions-original.css"><style>body{min-width:1100px}.fixture{position:absolute;left:30px;top:100px}.fixture:not(:first-child){visibility:hidden;pointer-events:none}#saveoptions-record{position:fixed;left:30px;top:20px}#language{position:fixed;left:600px;top:20px}#live{position:absolute;left:30px;top:320px;white-space:pre-wrap}</style><button id="saveoptions-record">Record SaveOptions</button><button id="language">Language</button><div id="fixtures"></div><pre id="live"></pre><script>'+script+'</script>')
for p in [o/'saveoptions-cases.json',r/'docs/replica/source/saveoptions-cases.json']:p.write_text(json.dumps(cases,indent=2)+'\n')
print(len(cases),'literal SaveOptions cases')
